# Montana Code Annotated from the legislature's own mca.legmt.gov: index -> title chapters_index -> chapter parts_index -> part sections_index -> each section page; text = the section-content paragraphs plus the History line.
import re

ROOT = 'https://mca.legmt.gov/bills/mca/'

def links(url, pattern):
    try:
        kind, body = fetch(url)
    except Exception as e:
        log('index failed %s: %s' % (url, e)); return []
    base = url.rsplit('/', 1)[0] + '/'
    out = []
    for h in re.findall(r'href="\./([^"#]+)"', body):
        if re.match(pattern, h) and base + h not in out:
            out.append(base + h)
    return out

def section(url):
    kind, page = fetch(url)
    end = page.find('mca-footer')
    segs = page[:end if end > 0 else len(page)].split('class="section-content"')[1:]
    if not segs:
        return None
    cat = ' '.join(block_text(page, cls='catchline').split())
    m = re.match(r'^(\d+-\d+-\d+(?:\.\d+)?[A-Z]?)\s*\.?\s*(.*)$', cat)
    if not m:
        return None
    sid, heading = m.group(1), m.group(2).strip()
    versions = []
    for seg in segs:            # a section in force in two versions (temporary / effective) prints both
        paras = [' '.join(p.split()) for p in block_texts(seg, cls='line-indent')]
        paras = [p for p in paras if p]
        if paras and paras[0].startswith(cat):
            paras[0] = paras[0][len(cat):].strip()
            if not paras[0]:
                paras = paras[1:]
        versions.append('\n'.join(paras))
    text = '\n\n'.join(v for v in versions if v) or heading
    if heading.rstrip('.') in ('Repealed', 'Terminated', 'Renumbered', 'Omitted', 'Expired', 'Transferred', 'Superseded', 'Void') and not text.startswith(heading):
        text = heading + ' ' + text          # "Repealed. Sec. 11, Ch. 610, L. 1987." — the status is the catchline
    return {'id': sid, 'heading': heading.rstrip('.').strip() or sid, 'text': text, 'url': url}

def sections():
    titles = [t for t in links(ROOT + 'index.html', r'title_\d{4}/chapters_index\.html$') if '/title_0000/' not in t]   # title 0 is the Constitution, not the code
    log('titles: %d' % len(titles))
    seen = set()
    for t in titles:
        n = 0
        for c in links(t, r'(?:chapter|article)_\d{4}/parts_index\.html$'):
            for p in links(c, r'part_\d{4}/sections_index\.html$'):
                for s in links(p, r'section_\d{4}/[\w-]+\.html$'):
                    try:
                        it = section(s)
                    except Exception as e:
                        log('section failed %s: %s' % (s, e)); continue
                    if it and it['id'] not in seen:
                        seen.add(it['id']); n += 1
                        yield it
        log('%s: %d sections' % (t.split('/')[-2], n))
